import sqlite3, glob, datetime
def con(f): return sqlite3.connect(f'file:{f}?mode=ro&immutable=1', uri=True)
def show(v, n=200):
    if isinstance(v, bytes):
        return f'<{len(v)} bytes> hex={v[:n].hex()} | ascii={"".join(chr(b) if 32<=b<127 else "." for b in v[:n])}'
    return repr(v)
idx = glob.glob('Data/*.ezdataindex')[0]; ev = glob.glob('Data/*.ezevents')[0]
mdb = glob.glob('Data/*[0-9].mediadb')[0]; mdb1 = glob.glob('Data/*-1.mediadb')[0]
c = con(idx)
for t in ['MediaHeader','MiscInfo','SchemaUpdateLog','PcTimeSync','synctable','TrackInfo']:
    print(f'\n##### {idx} :: {t}')
    for row in c.execute(f'select * from "{t}"'):
        print('  ', [show(v, 400 if t=='TrackInfo' else 200) for v in row])
print(f'\n##### FrameInfo (index) first 8 / last 3')
rows = c.execute('select * from FrameInfo order by Track, Offset').fetchall()
for r in rows[:8]+rows[-3:]: print('  ', r)
print('tracks/status/fileindex:', c.execute('select Track, Status, FileIndex, JoinDatabase, count(*) from FrameInfo group by 1,2,3,4').fetchall())
c = con(ev)
print(f'\n##### ezevents MediaHeader/SchemaUpdateLog')
for t in ['MediaHeader','SchemaUpdateLog']:
    for row in c.execute(f'select * from "{t}"'): print('  ', t, [show(v) for v in row])
print('\n##### Events')
for row in c.execute('select EventType, Text, StartTime, EndTime, StartOffset, EndOffset, Priority, Display, EventManipulation, Deleted, SourceApplicationId, WhenEnteredTime, Attributes from Events order by StartTime'):
    print('  ', [show(v, 60) for v in row])
c = con(mdb)
print(f'\n##### {mdb} FrameInfo (first 6) + MiscInfo + SchemaUpdateLog')
rows = c.execute('select * from FrameInfo order by Track, TimeStamp').fetchall()
for r in rows[:6]+rows[-2:]: print('  ', r)
print('  tracks:', c.execute('select Track, Status, JoinDatabase, count(*) from FrameInfo group by 1,2,3').fetchall())
for t in ['MiscInfo','SchemaUpdateLog']:
    for row in c.execute(f'select * from "{t}"'): print('  ', t, [show(v, 300) for v in row])
c = con(mdb1)
print(f'\n##### {mdb1} blob sizes')
sizes = c.execute('select DataKey, length(Data) from FrameInfo').fetchall()
from collections import Counter
print('  size histogram:', Counter(s for _, s in sizes).most_common())
print('  total bytes:', sum(s for _, s in sizes))
for t in ['MiscInfo','SchemaUpdateLog']:
    for row in c.execute(f'select * from "{t}"'): print('  ', t, [show(v, 300) for v in row])
key, blob = c.execute('select DataKey, Data from FrameInfo order by rowid limit 1').fetchone()
print('  first blob key', key.hex() if isinstance(key, bytes) else key)
print('  first 256 bytes:', blob[:256].hex())
print('  ascii:', "".join(chr(b) if 32<=b<127 else "." for b in blob[:256]))
# does the mediadb FrameInfo FrameKey match DataKey in -1?
ck = con(mdb).execute('select FrameKey from FrameInfo limit 3').fetchall()
print('  mediadb FrameKeys sample:', [show(k[0], 16) for k in ck])
print('  -1 DataKeys sample:', [show(s[0], 16) for s in sizes[:3]])
EOF

